/**
 * lote20.php — Los requisitos de la carga, y la comparación con el conductor.
 *
 * REQUIERE los lotes 12 a 19 aplicados.
 *
 * Es la otra mitad del bloque. El lote 18 puso los HECHOS del conductor; esto
 * pone las PREGUNTAS de la carga y quien las compara.
 *
 * Qué instala:
 *   • La tabla `load_requirements`: TWIC, endorsement, autorización de trabajo
 *     y récord limpio de N años. Con aislamiento entre empresas por clave
 *     compuesta y su CHECK.
 *   • `App\Support\Loads\DriverEligibility`: función PURA que compara y
 *     devuelve cumple / no cumple / NO CONSTA, requisito a requisito. No
 *     descarta a nadie, no bloquea una asignación, no esconde a un conductor de
 *     ninguna lista. Devuelve un veredicto; asigna una persona.
 *   • El editor de requisitos en el formulario de la carga.
 *   • El veredicto guardado en `load_assignments.compliance_snapshot` al
 *     asignar — esa columna ya existía en el esquema esperando esto. Si dentro
 *     de un año alguien pregunta por qué se le dio esta carga a esa persona, la
 *     columna responde con lo que se sabía ENTONCES.
 *   • 17 pruebas del motor, sin base de datos.
 *
 * DOS COSAS QUE NO SON DE ESTILO
 *
 *   • «NO CONSTA» no se colapsa en «no cumple». Un dato que nadie ha mirado se
 *     arregla mirándolo, no buscando otro conductor. Juntarlos enseñaría a la
 *     gente a ignorar los avisos, que es la única manera de que un aviso deje
 *     de servir para nada.
 *   • Un requisito de autorización de trabajo OBLIGA a decir de dónde sale: el
 *     contrato, la base o el cliente que lo exige. El servidor no lo guarda sin
 *     eso. Exigir ciudadanía sin un contrato que la pida por escrito es
 *     discriminación por estatus migratorio (8 U.S.C. § 1324b), no una regla de
 *     negocio, y ese campo es lo que separa una cosa de la otra el día que
 *     alguien pregunte. No soy abogado: que lo mire el tuyo antes de producción.
 *
 * La migración es REANUDABLE y su DDL se ejecutó contra un MySQL 8.0.46 real
 * con tu esquema entero cargado: desde cero, sobre lo ya creado, y desde un
 * estado a medias.
 *
 * Cómo se ejecuta, desde la raíz del repositorio:
 *
 *     php lote20.php            # aplica
 *     php lote20.php --dry-run  # dice qué haría y no toca nada
 */

$raiz = __DIR__;
$dry = in_array('--dry-run', $argv, true);
$hechos = []; $saltados = []; $errores = [];

function ruta(string $rel): string { global $raiz; return $raiz.DIRECTORY_SEPARATOR.$rel; }

function nuevo(string $rel, string $contenido): void
{
    global $dry, $hechos, $saltados, $errores;
    $destino = ruta($rel);
    if (is_file($destino) && file_get_contents($destino) === $contenido) { $saltados[] = "= {$rel}"; return; }
    $existia = is_file($destino);
    if ($dry) { $hechos[] = ($existia ? '~ ' : '+ ').$rel; return; }
    $dir = dirname($destino);
    if (! is_dir($dir) && ! mkdir($dir, 0775, true) && ! is_dir($dir)) { $errores[] = "no se pudo crear el directorio {$dir}"; return; }
    if (file_put_contents($destino, $contenido) === false) { $errores[] = "no se pudo escribir {$rel}"; return; }
    $hechos[] = ($existia ? '~ ' : '+ ').$rel;
}

/**
 * Aplica trozos anclados. Si el resultado ya está, se salta; si el texto de
 * partida está una sola vez, se sustituye; si no, se aborta el fichero entero
 * sin escribir — un anclaje que no encaja significa que el fichero no es el que
 * este guion vio, y adivinar ahí es peor que parar.
 *
 * @param  list<array{0: string, 1: string}>  $pares
 */
function editar(string $rel, array $pares): void
{
    global $dry, $hechos, $saltados, $errores;
    $destino = ruta($rel);
    if (! is_file($destino)) { $errores[] = "falta {$rel} — ¿está en la raíz del repositorio?"; return; }
    $texto = file_get_contents($destino); $aplicados = 0; $yaEstaban = 0;
    foreach ($pares as $i => [$antes, $despues]) {
        if (str_contains($texto, $despues)) { $yaEstaban++; continue; }
        $veces = substr_count($texto, $antes);
        if ($veces !== 1) { $errores[] = "{$rel}: el trozo #".($i + 1)." no encaja ({$veces} coincidencias). No se tocó el fichero."; return; }
        $texto = str_replace($antes, $despues, $texto); $aplicados++;
    }
    if ($aplicados === 0) { $saltados[] = "= {$rel} ({$yaEstaban} trozo(s) ya estaban)"; return; }
    if ($dry) { $hechos[] = "~ {$rel} ({$aplicados} trozo(s))"; return; }
    if (file_put_contents($destino, $texto) === false) { $errores[] = "no se pudo escribir {$rel}"; return; }
    $hechos[] = "~ {$rel} ({$aplicados} trozo(s))";
}

foreach (['artisan', 'composer.json', 'app/Support/Navigation.php'] as $centinela) {
    if (! is_file(ruta($centinela))) {
        fwrite(STDERR, "Esto no parece la raíz del repositorio: falta {$centinela}.\n");
        exit(1);
    }
}

